function countSubsetsWithSum(nums, target) {
  let found = 0;
  const total = 1 << nums.length;
  for (let mask = 0; mask < total; mask++) {
    let sum = 0;
    for (let i = 0; i < nums.length; i++) {
      if (mask & (1 << i)) sum += nums[i];
    }
    if (sum === target) found += 1;
  }
  return found;
