function completions(nums, index, sum, target) {
  if (index === nums.length) return sum === target ? 1 : 0;
  const taking = completions(nums, index + 1, sum + nums[index], target);
  const skipping = completions(nums, index + 1, sum, target);
  return taking + skipping;
}

function countSubsetsWithSum(nums, target) {
  return completions(nums, 0, 0, target);
}

